<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Brand; use App\Services\AuditService; use Illuminate\Http\Request;
class BrandController extends Controller { public function index(){$this->authorize('manage',Brand::class);return view('admin.brands.index',['brands'=>Brand::withCount(['pages','services','courses','users'])->orderBy('name')->get()]);} public function create(){ $this->authorize('manage',Brand::class);return view('admin.brands.form',['item'=>new Brand]);} public function store(Request $r,AuditService $audit){$this->authorize('manage',Brand::class);$b=Brand::create($this->valid($r));$audit->record('brands.created',$b,[],$b->toArray(),$b->id);return redirect()->route('admin.brands.edit',$b)->with('status','品牌已建立。');} public function edit(Brand $brand){$this->authorize('manage',Brand::class);return view('admin.brands.form',['item'=>$brand]);} public function update(Request $r,Brand $brand,AuditService $audit){$this->authorize('manage',Brand::class);$before=$brand->toArray();$brand->update($this->valid($r,$brand));$audit->record('brands.updated',$brand,$before,$brand->fresh()->toArray(),$brand->id);return back()->with('status','品牌已更新。');} public function destroy(Brand $brand,AuditService $audit){$this->authorize('manage',Brand::class);abort_if($brand->users()->where('role','super_admin')->exists(),422,'不可刪除仍有總管理者的品牌。');$audit->record('brands.deleted',$brand,$brand->toArray(),[],$brand->id);$brand->delete();return redirect()->route('admin.brands.index')->with('status','品牌已刪除。');} private function valid(Request $r,?Brand $b=null):array{$data=$r->validate(['name'=>'required|string|max:160','slug'=>'required|alpha_dash|max:100|unique:brands,slug,'.($b?->id??'NULL'),'domain'=>['nullable','max:255','regex:/^(?=.{1,253}$)(?!-)[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*(?<!-)$/','unique:brands,domain,'.($b?->id??'NULL')],'status'=>'required|in:active,inactive','primary_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','secondary_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','accent_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','background_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','text_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:1000']);$data['theme_settings']=$b?->theme_settings??[];return $data;}}
